// Entirely authored file-backed PCM/catalogue and executable identities.
// Uses the actual loaders, runtime, host, Node producer and renderer; no GTA assets.
import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';
const [root,host,game]=process.argv.slice(2),repo=path.resolve(import.meta.dirname,'../..'),sha=b=>createHash('sha256').update(b).digest('hex');
if(!root||fs.existsSync(root)||!path.resolve(root).startsWith(path.join(repo,'.local')+path.sep))throw Error('Fresh private fixture root required');
fs.mkdirSync(root,{recursive:true});const json=(f,v)=>{const p=path.join(root,f);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,JSON.stringify(v));},copy=(from,to)=>{const p=path.join(root,to);fs.mkdirSync(path.dirname(p),{recursive:true});fs.copyFileSync(from,p);};
function walk(p){return fs.readdirSync(p,{withFileTypes:true}).flatMap(d=>d.isDirectory()?walk(path.join(p,d.name)):[path.join(p,d.name)]);}
for(const f of [...walk(path.join(repo,'src/acoustics')),...walk(path.join(repo,'tools/soundmap'))].filter(f=>f.endsWith('.mjs')))copy(f,path.relative(repo,f));
copy(path.join(repo,'tools/Run-Gameplay.mjs'),'tools/Run-Gameplay.mjs');copy(process.execPath,'runtime/node.exe');copy(host,'runtime/RichAudio.Acoustics.Host.exe');
const pcm=Buffer.alloc(8192*4);for(let i=0;i<8192;i++)pcm.writeFloatLE(.043*Math.sin(i*.119)+.021*Math.cos(i*.037),i*4);
const hash=sha(pcm),parser='b'.repeat(64),awc='a'.repeat(64),gameHash=sha(fs.readFileSync(game)),atlas=[],analysis=[],links=[];
function library(npc){const layers={},streams=[];let id=0;for(const role of ['engine','exhaust']){layers[role]={};for(const mode of npc?['idle','accel']:['idle','accel','decel']){
 const file=`${role}-${mode}.f32`;copyPcm(`sources/${npc?'npc':'player'}/${file}`);const spans=Array.from({length:8},(_,i)=>({startFrame:i*1024,endFrame:(i+1)*1024}));
 const asset={file,sha256:hash,frames:8192,sampleRate:24000,channels:1,sourceFormat:{codec:0},granular:{grains:Array.from({length:9},(_,i)=>({UnkUint1:i*1024}))}};layers[role][mode]=asset;
 const sid=npc?({engine_idle:0x1d18b9a1,engine_accel:0x1f7402aa,exhaust_idle:0x179ddcaa,exhaust_accel:0x03ab9171}[role+'_'+mode]):++id;
 streams.push({name:role+'_'+mode,hash:sid.toString(16).padStart(8,'0'),asset});
 if(!npc){analysis.push({model:'bati',layer:role,state:mode,file,frames:8192,sampleRate:24000,candidateIntervals:spans});atlas.push({model:'bati',role,state:mode,file,sha256:hash,frames:8192,sampleRate:24000,intervals:spans.map((s,index)=>({...s,index,rms:.035,crestDb:6,detailRatio:.1,transientRisk:false}))});links.push({State:'verified-installed-container-and-stream',CandidateCount:1,Candidates:[{Path:'original.awc'}],AwcSHA256:awc,MaskedAwcStreamId:sid.toString(16).padStart(8,'0'),FullRelStreamHash:sid.toString(16).padStart(8,'0'),Stream:{StreamId:sid.toString(16).padStart(8,'0'),Frames:8192,SampleRate:24000,Codec:0}});}
 }}return {schema:1,sourceAssemblies:{CodeWalkerCoreSha256:parser},gameExecutableSha256:gameHash,authoredFixture:true,vehicles:[{model:'bati',audioContext:npc?'npc':'player',...(npc?{sourceContract:'npc-four-state-v1'}:{}),provenance:{awcSha256:awc,entry:'original.awc',archive:'original.rpf'},streams,layers}]};}
function copyPcm(f){const p=path.join(root,f);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,pcm);}
json('sources/player/manifest.json',library(false));json('sources/npc/manifest.json',library(true));json('sources/player/analysis-intervals.json',{streams:analysis});json('sources/atlas.json',{schema:1,streams:atlas});json('sources/profiles.json',{profiles:{},emitters:{}});
json('sources/catalog.json',{Schema:1,Stage:'codewalker-resolved-installation-model',ParserErrorCount:0,InputBinding:{CodeWalkerCoreSHA256:parser,GameExecutableSHA256:gameHash},Vehicles:[{Model:'bati',ModelHash:'f9300cc5',Sounds:{EngineAccel:{ParserType:'Dat54GranularSound',ChannelLinks:links}}}],authoredFixture:true});
const manifest={schema:1,gameExecutable:path.resolve(game),gameSha256:gameHash,gameVersion:'1.0.1158.16',rphVersion:'functional-compatibility',demoProfile:'PLAYABLE-13',playerManifest:'sources/player/manifest.json',npcManifest:'sources/npc/manifest.json',atlas:'sources/atlas.json',profiles:'sources/profiles.json',catalog:'sources/catalog.json',catalogSha256:sha(fs.readFileSync(path.join(root,'sources/catalog.json'))),eligible:[{model:0xf9300cc5,context:'player'}],bindings:walk(root).map(f=>({file:path.relative(root,f).replaceAll('\\','/'),sha256:sha(fs.readFileSync(f))})),authoredFixture:true};json('playable.json',manifest);
json('.local/acoustic-settings.json',{schemaVersion:1,revision:1,acousticQuality:'balanced',acousticAcceleration:'auto',richAudioEnabled:true,outputLevel:1,earlyReflections:true,diagnosticsOverlay:true,integrationMode:'experimental-additive',soundMapVisible:false,menuToggleKey:'F10',airflowEnabled:true,airflowLevel:1});
console.log(JSON.stringify({root,bindings:manifest.bindings.length,authoredPcm:true,installedReads:false}));
